"""Minimal Entity Component System.

- Entities are plain integers.
- Component storage: one dict per component type: {entity_id: component}.
- Systems are plain functions registered on the World and executed in order.
- Destruction is deferred: it is queued and flushed at end of frame.
"""

from dataclasses import dataclass


class World:
    def __init__(self):
        self._next_id = 0
        self._components = {}      # type -> {entity: component}
        self._dead = set()         # destroyed entities pending removal
        self._systems = []         # [(name, function), ...]

    # -- entities ------------------------------------------------------

    def create(self):
        """Create a new entity id."""
        self._next_id += 1
        return self._next_id

    def destroy(self, entity):
        """Queue an entity for destruction (applied at end of frame)."""
        self._dead.add(entity)

    def alive(self, entity):
        return (
            0 < entity <= self._next_id
            and entity not in self._dead
        )

    # -- components ----------------------------------------------------

    def add(self, entity, component):
        """Attach one component instance to an entity."""
        self._components.setdefault(type(component), {})[entity] = component

    def get(self, entity, comp_type):
        """Return the component of `comp_type` on `entity`, or None."""
        return self._components.get(comp_type, {}).get(entity)

    def remove(self, entity, comp_type):
        """Detach a single component immediately."""
        self._components.get(comp_type, {}).pop(entity, None)

    def has(self, entity, comp_type):
        return entity in self._components.get(comp_type, {})

    # -- queries ---------------------------------------------------------

    def query(self, *comp_types):
        """Yield exactly the entities that hold ALL requested components."""
        if not comp_types:
            return
        tables = [self._components.get(t, {}) for t in comp_types]
        smallest = min(tables, key=len)
        for entity in smallest:
            if all(entity in t for t in tables):
                yield entity

    # -- systems ---------------------------------------------------------

    def register_system(self, name, fn):
        self._systems.append((name, fn))

    def step(self, dt=1.0):
        """Run all registered systems in order, then flush deferred destroys."""
        for _name, fn in self._systems:
            fn(self, dt)
        self._flush()

    def _flush(self):
        """Apply queued destructions: drop every trace of dead entities."""
        for entity in self._dead:
            for table in self._components.values():
                table.pop(entity, None)
        self._dead.clear()


# ---------------------------------------------------------------------------
# Components
# ---------------------------------------------------------------------------

@dataclass
class Position:
    x: float = 0.0
    y: float = 0.0


@dataclass
class Velocity:
    dx: float = 0.0
    dy: float = 0.0


@dataclass
class Collider:
    radius: float = 1.0


# ---------------------------------------------------------------------------
# Systems
# ---------------------------------------------------------------------------

ARENA_MIN, ARENA_MAX = 0.0, 100.0


def movement_system(world, dt):
    """Advance positions by velocity."""
    vel_table = world._components.get(Velocity, {})
    for entity, vel in vel_table.items():
        pos = world.get(entity, Position)
        if pos is not None:
            pos.x += vel.dx * dt
            pos.y += vel.dy * dt


def bounds_system(world, dt):
    """Clamp every positioned entity into the 100x100 arena."""
    pos_table = world._components.get(Position, {})
    for pos in pos_table.values():
        pos.x = min(max(pos.x, ARENA_MIN), ARENA_MAX)
        pos.y = min(max(pos.y, ARENA_MIN), ARENA_MAX)

